import{_ as i,o as t,b as l,q as r}from"./chunks/framework.Tf23FRXt.js";const a="/assets/151591.DLkGqwLx.png",o="/images/icons/061509.png",p="/images/icons/061515.png",s="/assets/adventurerplate.CHDcv7FG.jpg",n="/assets/housing.szz-5rWE.png",_=JSON.parse('{"title":"社群与社交","description":"","frontmatter":{},"headers":[{"level":2,"title":"招募板","slug":"招募板","link":"#招募板","children":[]},{"level":2,"title":"个人信息","slug":"个人信息","link":"#个人信息","children":[]},{"level":2,"title":"冒险者铭牌及肖像","slug":"冒险者铭牌及肖像","link":"#冒险者铭牌及肖像","children":[]},{"level":2,"title":"玩家部队","slug":"玩家部队","link":"#玩家部队","children":[]},{"level":2,"title":"住宅区与房屋","slug":"住宅区与房屋","link":"#住宅区与房屋","children":[{"level":3,"title":"房屋","slug":"房屋","link":"#房屋","children":[]},{"level":3,"title":"公寓","slug":"公寓","link":"#公寓","children":[]},{"level":3,"title":"房屋玩法","slug":"房屋玩法","link":"#房屋玩法","children":[]}]},{"level":2,"title":"通讯贝","slug":"通讯贝","link":"#通讯贝","children":[]},{"level":2,"title":"同好会","slug":"同好会","link":"#同好会","children":[]}],"relativePath":"topic/social.htm.md","filePath":"topic/social.md","lastUpdated":1791098838000}'),c={name:"topic/social.htm.md"};function d(h,e,g,m,f,k){return t(),l("div",null,[...e[0]||(e[0]=[r('<h1 id="社群与社交" tabindex="-1">社群与社交</h1><p>FF14 作为网游，也具有相当的社交功能，通过这些功能来寻找与自己志同道合的小伙伴吧！</p><h2 id="招募板" tabindex="-1">招募板</h2><div class="guide cols2"><div class="guide col"><p><img src="'+a+'" alt="" loading="lazy"></p></div><div class="guide col grow"><p>在菜单 &gt; 小队 &gt; 队员招募中可以打开招募板，国服玩家大都通过招募板进行高难度副本或其他游戏内容的组队。</p><p>在招募板的 “其他” 分类里会有大量 RP 店的广告、商人出售装备的广告等等（如果看到有买卖金、买卖房的广告请不要相信，顺手点一波举报维护游戏环境哦～<a href="https://actff1.web.sdo.com/project/20210621ffviolation/index.html#/index" target="_blank" rel="noreferrer"> 违规处理平台</a>）。如果你想尝试社交活动，却又不得其门而入，可以先看看招募板，找找感兴趣的招募哦～</p></div></div><h2 id="个人信息" tabindex="-1">个人信息</h2><p>打开小队窗口（菜单 &gt; 小队 &gt; 小队队员，默认快捷键 <code>O</code> ），右键自己的名字可以<mark>编辑信息</mark>：</p><ul><li>名字下方的下拉菜单可以修改自己的在线状态，如果不想显示任何图标，可以选择<mark>在线</mark>。 <ul><li>若状态为<img src="'+o+'" class="no-zoom sm-icon"><mark>忙碌中</mark>，则会自动拒绝所有交易申请。</li><li>若状态为<img src="'+p+'" class="no-zoom sm-icon"><mark>希望组队</mark>，则下方的职业按钮会亮起；被选中的职业均会在玩家搜索的结果中展示。（比如我同时点亮了战士和白魔，与此同时我目前的职业是召唤，那么无论搜索战士，还是白魔或召唤，都可以在搜索结果中找到我）</li><li>完整的状态列表可以参见<a href="https://ff14.huijiwiki.com/wiki/%E5%9C%A8%E7%BA%BF%E7%8A%B6%E6%80%81" target="_blank" rel="noreferrer"> wiki 上的相关介绍</a></li></ul></li><li>最下方的个人签名会显示在玩家的个人信息中（右键玩家<mark>调查</mark>，鼠标放在 ID 名字前面的气泡符号上可以查看）。</li></ul><h2 id="冒险者铭牌及肖像" tabindex="-1">冒险者铭牌及肖像</h2><div class="guide cols2"><div class="guide col"><img src="'+s+'" width="350px"><p>冒险者铭牌</p></div><div class="guide col grow"><p>冒险者铭牌是一套可以展示角色和玩家信息的角色卡系统，分为冒险者名牌和肖像列表两部分。在<mark>菜单 &gt; 角色 &gt; 冒险者铭牌</mark>中，可以打开冒险者铭牌及其相关设置。而在<mark>菜单 &gt; 角色 &gt; 肖像列表</mark>中，可以针对已保存的套装编辑肖像。</p><p>将肖像设置为任务用肖像之后，可以在<a href="/topic/pvp.htm">水晶冲突</a>和<a href="/topic/gs-mahjong.htm">多玛方城战</a>开场时，以及进入副本时进行展示。</p><p>将冒险者铭牌设为所有人可见之后，所有人都可以右键你的名字 &gt; 查看冒险者铭牌。</p></div></div><blockquote><p><a href="/topic/plate.htm">如何制作冒险者铭牌和肖像</a></p></blockquote><h2 id="玩家部队" tabindex="-1">玩家部队</h2><p>部队是由玩家自行组成的工会系统，部队成员的一切游戏内活动都可以为部队带来战绩，部队战绩则可以用于兑换部队使用的 buff、飞空艇 / 潜水艇燃料、家具等等。<a href="https://bbs.nga.cn/read.php?tid=22764977" target="_blank" rel="noreferrer">部队战绩如何获得</a></p><p>新玩家只能被他人邀请加入部队。进入部队后，除了能获得部队 buff 的加成，也可以使用部队频道（ <code>/fc</code> ）随时随地与部队成员交流，更轻松方便地进行游戏。有的部队会定期组织各种小活动，有的部队还会在部队储物柜中存放一些赠送新人的小礼物等等。</p><p><strong>注意：部队储物柜储存的物品 / 资金为全部队共有，部队长可以设置成员组使用权限，切勿当做个人仓库使用。另外从部队储物柜中拿东西的时候，也请尽量告知其他部队成员，以免造成误会。</strong></p><p>如果你加入的部队有自己的部队房屋，你还可以以较低的价格，在部队房屋中购买宿舍，宿舍和其他个人房屋一样，可以进行装修等玩法。同时部队房屋还会拥有部队工房，在工房内可以合建飞空艇、潜水艇，派遣探索会有概率获得稀有道具。</p><p>如果你觉得自己所在的部队不舒服、不喜欢，也可以随时退出（有部队宿舍的玩家需要先退宿舍）。怀着友好的心情去寻找属于你的那份友谊吧！</p><p>关于建立部队、部队 buff、工房等相关内容的详细信息，请参看<a href="https://ff14.huijiwiki.com/wiki/%E9%83%A8%E9%98%9F" target="_blank" rel="noreferrer"> wiki 上的介绍页面</a>。</p><h2 id="住宅区与房屋" tabindex="-1">住宅区与房屋</h2><div class="guide col"><img src="'+n+'"><p>初始三城房区概念图</p></div><p>在利姆萨・罗敏萨、格里达尼亚、乌尔达哈、黄金港和伊修加德，有各城邦国家为冒险者准备的住宅小区。玩家可以通过完成住宅区任务或从野外入口（黄金港住宅区没有野外入口）直接进入。</p><p>每个住宅区有 24 个小区，每个小区分为初始区（房号 1~30）和扩展区（房号 31~60），另外每个区还单独配有一栋公寓楼。初始区和扩展区的房屋 / 景色分布一致，但朝向不同。</p><h3 id="房屋" tabindex="-1">房屋</h3><p>住宅区内的地块分为大中小 3 种尺寸，每种尺寸又分为 1~5 等，这些分类会影响地块的售价，以及可建造房屋的大小。大尺寸地块只能建大型房屋，小尺寸地块只能建小型房屋。</p><p>玩家可以通过点击未出售地块门前的门牌进行购买（目前为抽选制，即需要在门牌支付全款登记购买意向，等抽选结束后获得土地所有权，或收回抽选资金），地块可以购买为个人房屋或部队房屋（目前为小区指定，个人房小区不可购买部队房、部队房小区不可购买个人房），每名玩家只能拥有至多 1 个个人房和 1 个部队房（部队房为全部队成员共享）。 <strong>如果同一账号下角色拥有房屋数量超过该限制，将会被系统判定为违规账号并进行处罚。</strong> 当房屋超过 45 天无人进入时，会被系统自动回收（个人房必须房主进入，部队房只要有部队成员进入即可）。</p><p>房屋庭院可以放置园圃进行杂交种植，还可以放置鸟棚，喂养、训练搭档陆行鸟。</p><p>部队房可以设置部队工房，进行飞空艇、潜水艇以及其他大型建设项目的合建。部队成员可以在部队房内购买宿舍间，宿舍是玩家可以购买到的最便宜的房间。</p><blockquote><ul><li><a href="https://house.ffxiv.cyou/#/" target="_blank" rel="noreferrer">艾欧泽亚售楼中心</a>：查看目前正在出售的房屋信息</li><li>关于房屋购买、权限、搬家等更多更详细的信息，可以查看<a href="https://ff14.huijiwiki.com/wiki/%E6%88%BF%E5%B1%8B" target="_blank" rel="noreferrer"> wiki 介绍页面</a>。</li></ul></blockquote><h3 id="公寓" tabindex="-1">公寓</h3><p>每个小区都配有一栋公寓楼，每栋公寓有 512 个房间，理论上说可以人手一间公寓还有富余。</p><p>公寓的房间面积 / 容量和部队宿舍一样，公寓楼门口有公共的鸟棚可以用来练鸟。</p><h3 id="房屋玩法" tabindex="-1">房屋玩法</h3><p>所有的房屋、房间都可以进行装修，很多玩家会将装修好的房屋作为 “店铺” 开放，这些店铺经常会在招募板上进行宣传，有兴趣的玩家可以关注招募板上的信息。</p><p>除了店铺之外，也有讲座、剧场、其他游戏捏他、迷宫等等多种类型的社交玩法，甚至有联合一整个小区的房屋做出 “花街” 商业区似的做法。这些信息都可以在<a href="https://weibo.com/n/%E8%89%BE%E6%AC%A7%E6%B3%BD%E4%BA%9ARP%E6%83%85%E6%8A%A5%E7%AB%99" target="_blank" rel="noreferrer"> @艾欧泽亚 RP 情报站</a>上找到。</p><p>装修本身也是玩家们中意的玩法，无论是古典、乡村、现代、蒸汽朋克、未来科技乃至实验艺术风格，都有玩家涉猎，是充满设计和动手操作乐趣的玩法。</p><blockquote><p>有以下一些网站可以查看装修相关的信息：</p><ul><li><a href="https://weibo.com/u/6255557911" target="_blank" rel="noreferrer">@艾欧泽亚装修办</a>：国内装修玩家投稿网站</li><li><a href="https://ff14housing.com/" target="_blank" rel="noreferrer">FF14 ハウジング</a>：FF14 家具预览网站，虽然有中文版，但是更新速度较慢，建议使用英语 / 日语版，查到家具名称后前往 wiki 搜索。</li><li><a href="https://housingsnap.com/" target="_blank" rel="noreferrer">FF14 ハウジング SS</a>：日服装修投稿网站</li><li>在社交媒体上搜索 #FF14housing #FFXIVhousing #FF14 ハウジング #FF14 装修 之类的话题，B 站也有大量装修视频教程。</li></ul></blockquote><h2 id="通讯贝" tabindex="-1">通讯贝</h2><p>通讯贝是类似于 QQ 群的游戏内通信群，每名玩家可以加入 8 个本服通讯贝（ <code>/l1~/l8</code> ），以及 8 个跨服通讯贝（ <code>/cwl1~/cwl8</code> ）。</p><p>如果你有好友需要交流，但不方便变更部队，就可以加入通讯贝来沟通。</p><p>另外通讯贝也经常用于亲友闲聊、RP 活动、播报狩猎信息、特殊 fate 信息，或者组队攻略游戏内容等等，可随意使用。</p><p>在三主城都有<strong>通讯贝发行人</strong>，找他们对话就可以建立通讯贝。创立者和设定的 “队长” 可以邀请他人进入通讯贝，被邀请的玩家需要在通讯贝界面进行确认。</p><p>游戏中其他交流方式可以参看<a href="/basic/communication.htm">本页</a>了解。</p><h2 id="同好会" tabindex="-1">同好会</h2><p>同好会是类似论坛的社群形式，玩家可以通过菜单 &gt; 社交 &gt; 同好会搜索并加入同好会。会长可以通过同好会吸收有相同志向、乐趣的玩家，也可以发布活动公告，在同好会的成员可以参与投票、发表留言（最多记录最近 100 件）。</p>',43)])])}const b=i(c,[["render",d]]);export{_ as __pageData,b as default};
